"""Publish only public contracts and source inventories; evaluator stays private."""
import argparse
import json
from pathlib import Path
import shutil
from common import dump,sha,SEEDS

def main(a):
    here=Path(__file__).resolve().parent;cases=json.loads((here/'cases.json').read_text());dataset=json.loads(a.dataset.read_text());schema=json.loads((here/'bindings.schema.json').read_text());a.output.mkdir(parents=True,exist_ok=True)
    for entry in dataset['assets']:
        case=entry['case_id']
        if case not in a.case:continue
        inventory_path=a.references/case/'source_inventory.json';inv=json.loads(inventory_path.read_text())
        public={k:inv[k] for k in ['case_id','source_files','source_coverage_complete','coverage_note','source_body_role_requirements'] if k in inv}
        public['parts']=[{k:p[k] for k in ['source_id','source_file','frame','required','vertices','triangles','bounds_m','area_m2','abs_volume_m3']} for p in inv['parts']]
        public_path=a.output/(case+'_source_inventory.json');dump(public_path,public)
        spec=cases['cases'][case]
        snapshot=here/'frozen'/case
        snapshot.mkdir(parents=True,exist_ok=False)
        for filename in ['common.py','geometry.py','structural.py','solver.py','evaluate.py','bindings.schema.json','case_hooks.py']:
            shutil.copy2(here/filename,snapshot/filename)
        dump(snapshot/'cases.json',{'schema_version':cases['schema_version'],'seeds':SEEDS,'common':cases['common'],'cases':{case:spec}})
        code_hashes={p.name:sha(p) for p in snapshot.iterdir() if p.is_file()}
        dump(snapshot/'frozen_manifest.json',{'case_id':case,'reference_inventory':str(inventory_path),'reference_inventory_sha256':sha(inventory_path),'code_sha256':code_hashes,'public_inventory_sha256':sha(public_path)})
        required_body=', '.join(spec['required_body_roles']);required_joint=', '.join(spec['required_joint_roles'])
        task=f"Using the unchanged original {entry['title']} source closure, author a physically simulated articulated USD mechanism that retains the source geometry and component identity. {spec['acceptance']} Required body roles: {required_body}. Required joint roles: {required_joint}. The evaluator applies its own bounded efforts and opens your final scene in a fresh solver; do not rely on your controller script or animation being executed. Read the public source inventory at {public_path}; map every required source_id once. Case-normalizing source filename lookup and reading cached FreeCAD BREP shapes is permitted, but preserve original files and record any derived repair. Independent source reference uses saved source geometry; it does not certify real hardware accuracy."
        contract="Save final.usd with metersPerUnit=1 and Z up. Retain each required original shape instance as a visible mesh (multiple mesh prims per source_id are permitted); map every instance once in bindings.json. Collision approximations may differ, but mark added collision-only primitives/meshes purpose=proxy/guide or invisible. Intended moving bodies must be dynamic/nonkinematic with finite positive mass and diagonal inertia. Base is static or explicitly kinematic. No time-sampled transforms/mesh points, prescribed pose updates, or substitute visual geometry. Declare ALL rigid bodies and ALL joints. Required joint_body_pairs are ordered: body0 is the listed parent and body1 is the listed child; this order is mandatory for the downstream load controller. Actual USD body0/body1/local frames/limits are read independently. Matrix convention is 4x4 column-vector rigid transform, translation in last column; no scale/shear/reflection. For source_assembly_world references, assembly_from_source is one rigid initial assembly alignment in meters. For part_local_only references, source_to_body is that part's rigid local alignment in meters. Preserve every original dependency. Source-to-body role requirements in public inventory are mandatory. Bindings JSON schema:\n"+json.dumps(schema,separators=(',',':'))
        public_acceptance={'scope':spec['acceptance'],'seeds':SEEDS,'required_body_roles':spec['required_body_roles'],'required_joint_roles':spec['required_joint_roles'],'joint_kinds':spec.get('joint_kinds',{}),'common':cases['common'],'task_parameters':{k:v for k,v in spec.items() if k not in ('acceptance','unsupported_reason','observer','partial_observer','required_body_roles','required_joint_roles','joint_kinds')},'controller_protocol':'12s, dt1/240: settle0-1s; ramp to task target1-5s; hold5-7s with a opposing load min(1% max effort, estimated downstream inertia times 1rad/s2) at5.5-6.5s; return7-9s; settle9-10s; bounded outward upper-limit test10-12s. Engine instead ramps crank through2pi+0.25rad from1-8s and holds; paired zero-load run uses same seed. Only world body forces and torques are applied; source transforms are never prescribed.','limits':'Mass/inertia/collision/geometry/closure/finite-state gates and native gravity witness apply. Source shape comparison is symmetric sampled surface distance plus all-vertex coverage with 3% area tolerance, not an exact topology equivalence proof.','decision_policy':'A concrete failed criterion is not accepted. Missing evaluator/import/runtime capability is INCONCLUSIVE, not demonstrated rejection or a false-pass.','source_inventory_sha256':sha(public_path),'source_inventory_file':str(public_path)}
        public_acceptance['joint_torque_abstraction']='Normal 9.81m/s2 gravity remains enabled. No per-body weight-cancelling force is applied. For each required revolute joint, Ieff is the sum over reachable dynamic child bodies of maximum native inertia eigenvalue plus m times squared perpendicular COM lever arm at the initial pose. Gravity feed-forward is minus the sum of dot(axis, cross(COM-origin, m*[0,0,-9.81])) over those bodies at the current pose. Command torque is clip(gravity_feedforward + Ieff*(36*(target-q)-6*qdot), -cap, cap) times one seed factor in [0.98,1.02]. Opposing hold torque is -min(0.01*cap,Ieff*1rad/s2) during5.5-6.5s. Equal/opposite axis torques go to joint body1/body0 when dynamic. Thus controller magnitude <=1.02*cap and controller plus hold load <=1.03*cap; the first50ms perturbation is <=0.005*min(cap,Ieff*1rad/s2). This is an abstract bounded joint actuator test. It does not establish native actuator sizing, tendon/lead-screw transmission, physical load ratings, or robot simulation readiness.'
        if spec['observer']=='door':public_acceptance['targets']='hinge +1.22rad relative to initial closed pose, then0; >=60deg reached and <=5deg closed. Upper-limit test must exercise authored upper stop.'
        if spec['observer']=='slider':public_acceptance['targets']='jaw_slide +0.03m relative to initial pose, then initial; >=0.02m measured travel; 1N opposing hold load; <=0.002m holding/return error. Upper-limit test must exercise authored upper stop.'
        if spec['observer']=='arm':public_acceptance['targets']='each required joint gets its corresponding target_offsets_rad relative to initial pose; targets held under opposing torque min(1% max effort, downstream effective inertia times 1rad/s2), return to initial.'
        if spec['observer']=='unsupported':public_acceptance['evaluator_limit']=spec['unsupported_reason']
        task_doc={'schema_version':'astra-content-value-task.v1','case_id':case,'frozen':True,'source_root':entry['source_root'],'primary_input':entry['primary_input'],'task':task,'submission_contract':contract,'public_acceptance':public_acceptance,'source_inventory_file':str(public_path),'source_inventory_sha256':sha(public_path),'private_reference_sha256':sha(inventory_path),'private_evaluator_cases_sha256':sha(snapshot/'cases.json'),'private_evaluator_snapshot':str(snapshot),'private_evaluator_snapshot_sha256':sha(snapshot/'frozen_manifest.json'),'freeze_basis':'Independent source inventory and synthetic positive/negative evaluator fixtures before either arm.'}
        dump(a.output/(case+'.json'),task_doc);print(case,sha(a.output/(case+'.json')))

if __name__=='__main__':
    p=argparse.ArgumentParser();p.add_argument('--dataset',type=Path,required=True);p.add_argument('--references',type=Path,required=True);p.add_argument('--output',type=Path,required=True);p.add_argument('--case',action='append',required=True);main(p.parse_args())
